def check_powers_of_2_mod_15():
    print("k | 2^k mod 15")
    for k in range(1, 10):
        power_of_2 = pow(2, k, 15)
        print(f"{k:2} | {power_of_2}")

# Check for 14 explicitly
required_residue = 14
found = False
for k in range(1, 10):
    if pow(2, k, 15) == required_residue:
        found = True
        break
if not found:
    print(f"\nResidue {required_residue} was not found in the tested powers.")
